using System;

// A class that owns something outside managed memory (here a pretend file handle).
class TempFile : IDisposable
{
    private readonly string _name;
    public TempFile(string name) { _name = name; Console.WriteLine("open  " + name); }
    // Dispose releases the outside resource now. The GC only frees memory, and later.
    public void Dispose() { Console.WriteLine("close " + _name); }
}

class Program
{
    // Time O(1), space O(1) apart from the 1 MB test array.
    static void Main()
    {
        int[] numbers = { 10, 20, 30 };
        Console.WriteLine("numbers = [10, 20, 30]");

        // 1) Memory safety: the CLR checks every array index while the program runs.
        try { Console.WriteLine(numbers[5]); }
        catch (IndexOutOfRangeException e) { Console.WriteLine("read numbers[5]: the CLR threw " + e.GetType().Name); }

        // 2) using calls Dispose at the closing brace, even if an exception is thrown inside.
        using (var file = new TempFile("report.csv"))
        {
            Console.WriteLine("write to report.csv");
        }

        // 3) Managed memory needs no free(): drop the reference and the GC reclaims it.
        var big = new byte[1000000];
        big = null;
        GC.Collect();
        Console.WriteLine("garbage collector has run at least once: " + (GC.CollectionCount(0) >= 1));
    }
}

