// Two namespaces in ONE assembly (this program). The same type name in each is no clash.
namespace Shop.Orders.Domain { public class Order { } internal class PriceRule { } }
namespace Shop.Orders.Api { public class Order { } }

class Program
{
    // Time O(n) for n types, space O(1).
    static void Main()
    {
        Type[] types =
        {
            typeof(Shop.Orders.Domain.Order), typeof(Shop.Orders.Api.Order),
            typeof(Shop.Orders.Domain.PriceRule), typeof(StringBuilder), typeof(List<int>)
        };
        var mine = typeof(Program).Assembly;      // the assembly = the compiled file of this program
        foreach (Type t in types)
        {
            // Namespace is only a prefix of the name; Assembly says which file the type lives in.
            Console.WriteLine("type " + t.Name.PadRight(14)
                + " namespace " + t.Namespace.PadRight(27)
                + " in this assembly: " + (t.Assembly == mine).ToString().PadRight(6)
                + " visible outside: " + t.IsPublic);
        }
        // One namespace (System.Collections.Generic) can also be spread over several assemblies.
        Console.WriteLine("List<int> and Program share an assembly: " + (typeof(List<int>).Assembly == mine));
    }
}

using System;
using System.Reflection;
using System.Runtime.InteropServices;

class Program
{
    static int Add(int a, int b) { return a + b; }

    // Time O(1), space O(1).
    static void Main()
    {
        // 1) The compiler stored CPU-neutral IL for Add in this assembly. Read it back.
        MethodInfo add = typeof(Program).GetMethod("Add", BindingFlags.NonPublic | BindingFlags.Static);
        byte[] il = add.GetMethodBody().GetILAsByteArray();
        Console.WriteLine("IL stored for Add: " + il.Length + " bytes (" + BitConverter.ToString(il) + ")");

        // 2) The JIT turns that IL into machine code the first time the method is called.
        Console.WriteLine("first call, JIT compiles it: Add(2, 3) = " + Add(2, 3));

        // 3) The runtime (CLR) that is executing us, and the CPU it produced code for.
        Console.WriteLine("runtime: " + RuntimeInformation.FrameworkDescription);
        Console.WriteLine("CPU architecture: " + RuntimeInformation.ProcessArchitecture);

        // 4) The BCL is ordinary assemblies too: this is the one that holds System.Object.
        Console.WriteLine("System.Object lives in: " + typeof(object).Assembly.GetName().Name);
        Console.WriteLine("Environment.Version: " + Environment.Version);
    }
}

using System;

class Program
{
    // A library method that must work on old and new targets.
    static int Clamp(int value, int min, int max)
    {
#if NETCOREAPP
        // Compiled only for modern .NET: the API exists there.
        return Math.Clamp(value, min, max);
#else
        // Compiled for older targets (.NET Framework, netstandard2.0): no Math.Clamp, write it by hand.
        return value < min ? min : (value > max ? max : value);
#endif
    }

    // Time O(1), space O(1).
    static void Main()
    {
        // The SDK defines one symbol per target, so each build takes exactly one branch.
#if NET8_0_OR_GREATER
        Console.WriteLine("compiled for: net8.0 or later (NET8_0_OR_GREATER is defined)");
#elif NETSTANDARD2_0
        Console.WriteLine("compiled for: netstandard2.0");
#else
        Console.WriteLine("compiled for: an older target (no modern symbol is defined)");
#endif
        int[] inputs = { -5, 42, 250 };
        foreach (int x in inputs)
            Console.WriteLine("Clamp(" + x + ", 0, 100) = " + Clamp(x, 0, 100));
        // Whichever branch was compiled, callers see the same behaviour.
    }
}

using System;

// A clock we control. TimeProvider is the built-in abstraction since .NET 8.
class FakeClock : TimeProvider
{
    private DateTimeOffset _now;
    public FakeClock(DateTimeOffset start) { _now = start; }
    public override DateTimeOffset GetUtcNow() => _now;
    public void Advance(TimeSpan by) => _now += by;
}

// Production code asks the injected clock, never DateTime.UtcNow directly.
class Trial
{
    private readonly TimeProvider _clock;
    private readonly DateTimeOffset _startedAt;
    public Trial(TimeProvider clock) { _clock = clock; _startedAt = clock.GetUtcNow(); }
    public int DaysLeft => 14 - (int)(_clock.GetUtcNow() - _startedAt).TotalDays;
    public bool IsExpired => DaysLeft <= 0;
}

class Program
{
    // Time O(1) per check, space O(1).
    static void Main()
    {
        var clock = new FakeClock(new DateTimeOffset(2026, 1, 1, 9, 0, 0, TimeSpan.Zero));
        var trial = new Trial(clock);
        Console.WriteLine("trial starts 2026-01-01, length 14 days");
        Console.WriteLine("day 0 : days left " + trial.DaysLeft + ", expired " + trial.IsExpired);

        clock.Advance(TimeSpan.FromDays(13));   // the test jumps 13 days in no time at all
        Console.WriteLine("day 13: days left " + trial.DaysLeft + ", expired " + trial.IsExpired);

        clock.Advance(TimeSpan.FromDays(1));
        Console.WriteLine("day 14: days left " + trial.DaysLeft + ", expired " + trial.IsExpired);

        // In production you pass the real clock instead.
        Console.WriteLine("real clock is usable too: " + (new Trial(TimeProvider.System).DaysLeft == 14));
    }
}

