using System;
using System.Collections.Generic;

// Same shape as ASP.NET Core: a middleware gets the context and "next".
delegate void Handler(List<string> log);
delegate Handler Middleware(Handler next);

class Program
{
    static Handler Build(List<Middleware> parts, Handler endpoint)
    {
        Handler h = endpoint;
        for (int i = parts.Count - 1; i >= 0; i--) h = parts[i](h);   // wrap from the end backwards
        return h;
    }

    // Time O(m) for m middleware per request, space O(m).
    static void Main()
    {
        Middleware logging = next => log => { log.Add("logging: before"); next(log); log.Add("logging: after"); };
        Middleware auth = next => log => { log.Add("auth: check user"); next(log); };
        Handler endpoint = log => log.Add("endpoint: run handler");

        var a = new List<string>();
        Build(new List<Middleware> { logging, auth }, endpoint)(a);
        Console.WriteLine("order logging, auth, endpoint:");
        foreach (var s in a) Console.WriteLine("  " + s);

        // Short circuit: this middleware never calls next, so the endpoint never runs.
        Middleware deny = next => log => log.Add("deny: 401, stop here");
        var b = new List<string>();
        Build(new List<Middleware> { logging, deny }, endpoint)(b);
        Console.WriteLine("order logging, deny, endpoint:");
        foreach (var s in b) Console.WriteLine("  " + s);
    }
}

