// A tiny stand-in for HttpContext.
class Ctx { public string Path = ""; public int Status = 200; public Dictionary<string, string> Headers = new Dictionary<string, string>(); }
delegate Task Next(Ctx c);

// Same shape as an ASP.NET Core middleware class: constructor takes next, InvokeAsync handles the request.
class TimingMiddleware
{
    private readonly Next _next;
    public TimingMiddleware(Next next) { _next = next; }
    public async Task InvokeAsync(Ctx ctx)
    {
        var watch = Stopwatch.StartNew();
        if (ctx.Path == "/blocked") { ctx.Status = 403; return; }   // short circuit: do not call next
        await _next(ctx);                                           // the rest of the pipeline
        ctx.Headers["X-Elapsed-Ms"] = watch.ElapsedMilliseconds >= 0 ? "measured" : "";
    }
}

class Program
{
    // Time O(1) per request, space O(1).
    static async Task Main()
    {
        Next endpoint = async c => { await Task.Delay(20); c.Status = 200; };
        var mw = new TimingMiddleware(endpoint);
        foreach (var path in new[] { "/orders", "/blocked" })
        {
            var ctx = new Ctx { Path = path };
            await mw.InvokeAsync(ctx);
            Console.WriteLine(path + " -> " + ctx.Status + ", X-Elapsed-Ms header set: " + ctx.Headers.ContainsKey("X-Elapsed-Ms"));
        }
    }
}

