using System;
using System.Collections.Generic;

// Typed settings, like a class you would bind with the Options pattern.
class SmtpOptions { public string Host = ""; public int Port; public bool Ssl; }

class Program
{
    // Apply sources in order: each later source overrides keys from earlier ones.
    // Time O(total keys), space O(keys).
    static Dictionary<string, string> Merge(params Dictionary<string, string>[] sources)
    {
        var result = new Dictionary<string, string>();
        foreach (var src in sources)
            foreach (var kv in src) result[kv.Key] = kv.Value;
        return result;
    }

    static void Main()
    {
        var appsettings = new Dictionary<string, string> { ["Smtp:Host"] = "localhost", ["Smtp:Port"] = "25", ["Smtp:Ssl"] = "false" };
        var envSpecific = new Dictionary<string, string> { ["Smtp:Host"] = "mail.staging.test" };
        var envVars = new Dictionary<string, string> { ["Smtp:Port"] = "587", ["Smtp:Ssl"] = "true" };

        var config = Merge(appsettings, envSpecific, envVars);   // later wins
        foreach (var kv in config) Console.WriteLine(kv.Key + " = " + kv.Value);

        // "Bind": copy the section into a typed object.
        var o = new SmtpOptions { Host = config["Smtp:Host"], Port = int.Parse(config["Smtp:Port"]), Ssl = bool.Parse(config["Smtp:Ssl"]) };
        Console.WriteLine("typed: " + o.Host + ":" + o.Port + " ssl=" + o.Ssl);
    }
}

using System;
using System.Collections.Generic;

class Counter { static int n; public int Id = ++n; }   // each new instance gets the next number

class Container
{
    private readonly Counter _singleton = new Counter();      // one for the whole app
    public Counter Singleton() => _singleton;
    public Counter Transient() => new Counter();              // new every time
    public Scope CreateScope() => new Scope();
}
class Scope
{
    private Counter _scoped;
    public Counter Scoped() { if (_scoped == null) _scoped = new Counter(); return _scoped; }   // one per scope
}
// A singleton that grabbed a scoped object: the captive dependency.
class CachedReport { public Counter Captive; public CachedReport(Counter scoped) { Captive = scoped; } }

class Program
{
    // Time O(1), space O(1).
    static void Main()
    {
        var c = new Container();
        for (int request = 1; request <= 2; request++)
        {
            var scope = c.CreateScope();    // one scope per HTTP request
            Console.WriteLine("request " + request + ": singleton #" + c.Singleton().Id
                + ", scoped #" + scope.Scoped().Id + " (same again: #" + scope.Scoped().Id + ")"
                + ", transient #" + c.Transient().Id + " and #" + c.Transient().Id);
        }
        var report = new CachedReport(c.CreateScope().Scoped());
        Console.WriteLine("captive dependency: the singleton keeps scoped #" + report.Captive.Id + " for ever");
    }
}

