using System;
using System.Collections.Generic;

class NotFoundException : Exception { public NotFoundException(string m) : base(m) { } }

class Problem   // fields of RFC 9457 Problem Details
{
    public int Status; public string Title; public string Detail; public string TraceId;
    public override string ToString() => "{ \"status\": " + Status + ", \"title\": \"" + Title + "\", \"detail\": \"" + Detail + "\", \"traceId\": \"" + TraceId + "\" }";
}

class Program
{
    // One place decides the status code and hides internals. Time O(1), space O(1).
    static Problem Map(Exception e, string traceId)
    {
        if (e is NotFoundException) return new Problem { Status = 404, Title = "Not Found", Detail = e.Message, TraceId = traceId };
        Console.WriteLine("  [server log] " + e);   // full error is logged here, never sent to the client
        return new Problem { Status = 500, Title = "Server Error", Detail = "An unexpected error occurred.", TraceId = traceId };
    }

    static void Handle(Action action, string traceId)
    {
        try { action(); }
        catch (Exception e) { Console.WriteLine("response: " + Map(e, traceId)); }
    }

    static void Main()
    {
        Handle(() => throw new NotFoundException("Order 42 was not found"), "trace-1001");
        Handle(() => { int[] a = new int[1]; a[3] = 1; }, "trace-1002");
    }
}

using System;
using System.Collections.Generic;

class Program
{
    static readonly HashSet<string> AllowedOrigins = new HashSet<string> { "https://shop.example.test" };
    static readonly HashSet<string> SimpleMethods = new HashSet<string> { "GET", "HEAD", "POST" };

    // What the API puts in its response. Time O(1), space O(1).
    static string Response(string origin) =>
        AllowedOrigins.Contains(origin) ? "Access-Control-Allow-Origin: " + origin : "(no CORS header)";

    // What the browser does: simple requests are sent; others get an OPTIONS preflight first.
    static void Call(string pageOrigin, string method)
    {
        bool preflight = !SimpleMethods.Contains(method);
        string header = Response(pageOrigin);
        bool allowed = header.StartsWith("Access-Control-Allow-Origin");
        Console.WriteLine(pageOrigin.PadRight(28) + method.PadRight(7)
            + " preflight: " + preflight.ToString().PadRight(5) + " | " + header.PadRight(60)
            + " -> " + (allowed ? "page can read the response" : "browser BLOCKS the response"));
    }

    static void Main()
    {
        Call("https://shop.example.test", "GET");
        Call("https://shop.example.test", "DELETE");
        Call("https://evil.example.test", "GET");
    }
}

using System;
using System.Collections.Generic;
using System.Threading.Tasks;

class Program
{
    static int calls;
    // A fake remote service that fails the first 3 times.
    static Task<string> CallService()
    {
        calls++;
        if (calls <= 3) throw new TimeoutException("attempt " + calls + " timed out");
        return Task.FromResult("200 OK");
    }

    // Retry up to maxAttempts; wait base * 2^attempt plus random jitter. Time O(attempts), space O(1).
    static async Task<string> WithRetry(int maxAttempts, int baseDelayMs)
    {
        var rng = new Random(1);                       // fixed seed so the output is repeatable
        for (int attempt = 1; ; attempt++)
        {
            try { return await CallService(); }
            catch (TimeoutException e) when (attempt < maxAttempts)
            {
                int delay = baseDelayMs * (1 << (attempt - 1));
                int jitter = rng.Next(0, delay / 2 + 1); // spread out clients that failed together
                Console.WriteLine(e.Message + "; wait " + (delay + jitter) + " ms (base " + delay + " + jitter " + jitter + ")");
                await Task.Delay(delay + jitter);
            }
        }
    }

    static async Task Main()
    {
        Console.WriteLine("result: " + await WithRetry(5, 10));
        Console.WriteLine("total calls: " + calls);
    }
}

using System;
using System.Threading;
using System.Threading.Tasks;

// Same loop shape as BackgroundService.ExecuteAsync(CancellationToken).
class Worker
{
    public int Processed;
    public async Task RunAsync(CancellationToken stop)
    {
        try
        {
            while (!stop.IsCancellationRequested)
            {
                Processed++;
                Console.WriteLine("processed batch " + Processed);
                await Task.Delay(50, stop);      // wait, but wake up at once when asked to stop
            }
        }
        catch (OperationCanceledException) { Console.WriteLine("stop requested while waiting"); }
        Console.WriteLine("cleanup done, worker finished");   // finish current work, then exit
    }
}

class Program
{
    // Time O(batches), space O(1).
    static async Task Main()
    {
        using (var cts = new CancellationTokenSource())
        {
            var worker = new Worker();
            Task running = worker.RunAsync(cts.Token);
            await Task.Delay(120);
            Console.WriteLine("host: shutting down");
            cts.Cancel();                         // what the host does on SIGTERM
            await running;
            Console.WriteLine("batches completed before stop: " + (worker.Processed >= 2));
        }
    }
}

