using System;
using System.Collections.Generic;

interface IProductRepo { string GetName(int id); }

class SlowRepo : IProductRepo
{
    public int DbCalls;
    public string GetName(int id) { DbCalls++; return "Product-" + id; }   // pretend this is a database query
}

// Same interface as what it wraps, adds caching, then calls the inner object.
class CachingRepo : IProductRepo
{
    private readonly IProductRepo _inner;
    private readonly Dictionary<int, string> _cache = new Dictionary<int, string>();
    public CachingRepo(IProductRepo inner) { _inner = inner; }
    public string GetName(int id)
    {
        string name;
        if (_cache.TryGetValue(id, out name)) return name;   // hit: the inner repo is not called
        name = _inner.GetName(id);
        _cache[id] = name;
        return name;
    }
}

class Program
{
    // Time O(1) per call, space O(n) cached items.
    static void Main()
    {
        var db = new SlowRepo();
        IProductRepo repo = new CachingRepo(db);   // callers only see the interface
        foreach (int id in new[] { 7, 7, 8, 7, 8 })
            Console.WriteLine("GetName(" + id + ") = " + repo.GetName(id));
        Console.WriteLine("calls: 5, database calls: " + db.DbCalls);
    }
}

using System;
using System.Collections.Generic;

interface IDiscount { decimal Apply(decimal total); }
class NoDiscount : IDiscount { public decimal Apply(decimal t) => t; }
class TenPercent : IDiscount { public decimal Apply(decimal t) => t * 0.9m; }
class FlatFive : IDiscount { public decimal Apply(decimal t) => Math.Max(0, t - 5m); }

class Checkout
{
    // Observer: anyone can subscribe to be told when an order is paid.
    public event Action<decimal> Paid;
    // Strategy: the rule is passed in, not hard-coded with if/else.
    public void Pay(decimal total, IDiscount rule)
    {
        decimal final = rule.Apply(total);
        Console.WriteLine(rule.GetType().Name.PadRight(11) + total + " -> " + final);
        if (Paid != null) Paid(final);
    }
}

class Program
{
    // Time O(subscribers) per payment, space O(subscribers).
    static void Main()
    {
        var checkout = new Checkout();
        decimal revenue = 0;
        checkout.Paid += amount => revenue += amount;                       // subscriber 1
        checkout.Paid += amount => Console.WriteLine("  email sent for " + amount);   // subscriber 2
        foreach (IDiscount rule in new IDiscount[] { new NoDiscount(), new TenPercent(), new FlatFive() })
            checkout.Pay(40m, rule);
        Console.WriteLine("revenue: " + revenue);
    }
}

