// Implements the same interface, does extra work, and passes the call on.
class LoggingOrderRepo : IOrderRepo
{
    private readonly IOrderRepo _inner;
    public LoggingOrderRepo(IOrderRepo inner) { _inner = inner; }
    public async Task<Order> GetAsync(int id)
    {
        var watch = Stopwatch.StartNew();
        try { return await _inner.GetAsync(id); }
        catch (Exception e) { Console.WriteLine("LOG error for id " + id + ": " + e.Message); throw; }   // throw; keeps the original stack
        finally { Console.WriteLine("LOG GetAsync(" + id + ") took >= 15 ms: " + (watch.ElapsedMilliseconds >= 10)); }
    }
}

class Program
{
    // Time O(1) added per call, space O(1).
    static async Task Main()
    {
