    }
}

using System;
using System.Collections.Generic;

class Program
{
    delegate string Handler(string request);

    // Wrap from the last middleware to the first, like ApplicationBuilder.Build().
    static Handler Build(List<Func<Handler, Handler>> parts, Handler end)
    {
        Handler h = end;
        for (int i = parts.Count - 1; i >= 0; i--) h = parts[i](h);
        return h;
    }

    // Time O(m) per request, space O(m).
    static void Main()
    {
        Func<Handler, Handler> authenticate = next => req => req.Contains("token") ? next(req + "+user") : "401 anonymous";
        Func<Handler, Handler> authorize = next => req => req.Contains("+user") ? next(req) : "403 no user to authorize";
        Handler endpoint = req => "200 secret data";

        var right = Build(new List<Func<Handler, Handler>> { authenticate, authorize }, endpoint);
        var wrong = Build(new List<Func<Handler, Handler>> { authorize, authenticate }, endpoint);

        Console.WriteLine("authenticate then authorize, with token : " + right("GET /data token"));
        Console.WriteLine("authenticate then authorize, no token   : " + right("GET /data"));
        Console.WriteLine("authorize then authenticate, with token : " + wrong("GET /data token"));   // order bug
    }
}

