class Program
{
    static int queries;
    static readonly Dictionary<int, string> Customers = new Dictionary<int, string> { [1] = "Ana", [2] = "Ben", [3] = "Cy" };
    static readonly List<(int id, int customerId)> Orders = new List<(int, int)> { (10, 1), (11, 2), (12, 3), (13, 1) };

