using System;
using System.Collections.Generic;
using System.Linq;

class OutboxMessage { public int Id; public string Type = ""; public string Payload = ""; public bool Sent; }

// One "database" with an orders table and an outbox table. Saving both is one atomic step.
class Db
{
    public List<string> Orders = new List<string>();
    public List<OutboxMessage> Outbox = new List<OutboxMessage>();
    public void SaveOrderAndEvent(string order)
    {
        Orders.Add(order);                                           // same transaction ...
        Outbox.Add(new OutboxMessage { Id = Outbox.Count + 1, Type = "OrderPlaced", Payload = order });   // ... so both or neither
    }
}

class Program
{
    static int attempt;
    // The message broker is unreliable: the first publish fails. Time O(n) per sweep, space O(1).
    static bool Publish(OutboxMessage m)
    {
        attempt++;
        if (attempt == 1) { Console.WriteLine("broker down, message " + m.Id + " not sent"); return false; }
        Console.WriteLine("published " + m.Type + " " + m.Payload); return true;
    }

    static void Relay(Db db)   // background job that sweeps unsent rows
    {
        foreach (var m in db.Outbox.Where(x => !x.Sent)) if (Publish(m)) m.Sent = true;
    }

    static void Main()
    {
        var db = new Db();
        db.SaveOrderAndEvent("order-17");
        Relay(db);   // fails once, but the row stays in the outbox
        Relay(db);   // retried, now sent
        Console.WriteLine("orders: " + db.Orders.Count + ", unsent events: " + db.Outbox.Count(x => !x.Sent));
    }
}

