    static Dictionary<string, List<string>> ValidateShape(OrderRequest r)
    {
        var errors = new Dictionary<string, List<string>>();
        if (string.IsNullOrWhiteSpace(r.Email) || !r.Email.Contains("@")) errors["Email"] = new List<string> { "must be a valid email address" };
        if (r.Quantity < 1 || r.Quantity > 100) errors["Quantity"] = new List<string> { "must be between 1 and 100" };
