        Console.WriteLine("request 1 -> 400 with " + ValidateShape(bad).Count + " errors:");
        foreach (var kv in ValidateShape(bad)) Console.WriteLine("  " + kv.Key + ": " + kv.Value[0]);

        var ok = new OrderRequest { Email = "ana@example.test", Quantity = 5 };
        Console.WriteLine("request 2 shape errors: " + ValidateShape(ok).Count);
        try { PlaceOrder(ok.Email, ok.Quantity, 3); }
