using System;

// Bucket holds up to 'capacity' tokens; a request needs one; tokens come back at a fixed rate.
class TokenBucket
{
    private readonly int _capacity;
    private readonly double _perSecond;
    private double _tokens;
    private double _lastSeconds;
    public TokenBucket(int capacity, double perSecond) { _capacity = capacity; _perSecond = perSecond; _tokens = capacity; }

    public bool TryTake(double nowSeconds)
    {
        _tokens = Math.Min(_capacity, _tokens + (nowSeconds - _lastSeconds) * _perSecond);   // refill
        _lastSeconds = nowSeconds;
        if (_tokens < 1) return false;     // out of tokens: the API answers 429 Too Many Requests
        _tokens -= 1;
        return true;
    }
}

class Program
{
    // Time O(1) per request, space O(1) per client.
    static void Main()
    {
        var bucket = new TokenBucket(3, 1.0);    // burst of 3, then 1 request per second
        double[] times = { 0.0, 0.1, 0.2, 0.3, 0.4, 1.4, 2.5 };
        foreach (double t in times)
            Console.WriteLine("t=" + t.ToString("0.0") + "s -> " + (bucket.TryTake(t) ? "200 OK" : "429 Too Many Requests"));
    }
}

