using System;

class Program
{
    // Counts digits in a slice. A span is a view over the same memory: no copy, no allocation.
    static int CountDigits(ReadOnlySpan<char> text)
    {
        int n = 0;
        foreach (char c in text) if (char.IsDigit(c)) n++;
        return n;
    }

    // Time O(n) for n characters, space O(1) when slicing with spans.
    static void Main()
    {
        string line = "ID-12345;NAME-ANA";
        Console.WriteLine("input: " + line);

        string copy = line.Substring(3, 5);          // allocates a new string of 5 chars
        ReadOnlySpan<char> view = line.AsSpan(3, 5); // same memory, just offset and length
        Console.WriteLine("Substring: " + copy + ", digits " + CountDigits(copy));
        Console.WriteLine("Span view : " + view.ToString() + ", digits " + CountDigits(view));

        long before = GC.GetAllocatedBytesForCurrentThread();
        int total = 0;
        for (int i = 0; i < 1000; i++) total += CountDigits(line.AsSpan(3, 5));
        long spanBytes = GC.GetAllocatedBytesForCurrentThread() - before;

        before = GC.GetAllocatedBytesForCurrentThread();
        for (int i = 0; i < 1000; i++) total += CountDigits(line.Substring(3, 5));
        long stringBytes = GC.GetAllocatedBytesForCurrentThread() - before;

        Console.WriteLine("1000 slices with spans allocate less than with Substring: " + (spanBytes < stringBytes));
        Console.WriteLine("total digits counted: " + total);
    }
}

using System;
using System.Diagnostics;
using System.Threading;
using System.Threading.Tasks;

class Program
{
    // Time depends on the pool size; space O(requests).
    static void Main()
    {
        ThreadPool.SetMinThreads(2, 2);
        ThreadPool.SetMaxThreads(2, 2);          // a tiny pool makes the problem easy to see
        const int requests = 6;

        var sw = Stopwatch.StartNew();
        var blocking = new Task[requests];
        for (int i = 0; i < requests; i++)
            blocking[i] = Task.Run(() => Task.Delay(300).Wait());   // each one holds a pool thread while waiting
        Task.WaitAll(blocking);
        long blockingMs = sw.ElapsedMilliseconds;

        sw.Restart();
        var asynchronous = new Task[requests];
        for (int i = 0; i < requests; i++)
            asynchronous[i] = Task.Run(async () => await Task.Delay(300));   // no thread is held during the wait
        Task.WaitAll(asynchronous);
        long asyncMs = sw.ElapsedMilliseconds;

        Console.WriteLine("pool size 2, 6 requests of 300 ms each");
        Console.WriteLine("blocking .Wait(): about " + (blockingMs / 100 * 100) + " ms (requests queue up)");
        Console.WriteLine("await          : about " + (asyncMs / 100 * 100) + " ms (all wait together)");
        Console.WriteLine("async finished faster: " + (asyncMs < blockingMs));
    }
}

