class Program
{
    static int evaluations;
    static IEnumerable<int> Numbers()
    {
        foreach (int n in new[] { 1, 2, 3, 4 }) { evaluations++; yield return n; }   // yield: values are produced on demand
    }

    // Time O(n) per enumeration, space O(1) for the lazy query.
    static void Main()
    {
        var query = Numbers().Where(n => n % 2 == 0);   // nothing has run yet
        Console.WriteLine("after defining the query, source items read: " + evaluations);
        Console.WriteLine("first loop : " + string.Join(",", query));
        Console.WriteLine("second loop: " + string.Join(",", query) + "  (it ran again)");
        Console.WriteLine("source items read in total: " + evaluations);
        var snapshot = query.ToList();                  // run once and keep the result
        Console.WriteLine("ToList stored " + snapshot.Count + " items, reading them again costs nothing");

        // Left join with GroupJoin + DefaultIfEmpty
        var people = new[] { new { Id = 1, Name = "Ana" }, new { Id = 2, Name = "Ben" } };
        var orders = new[] { new { PersonId = 1, Item = "Book" } };
        var left = from p in people
                   join o in orders on p.Id equals o.PersonId into g
                   from o in g.DefaultIfEmpty()
                   select p.Name + " -> " + (o == null ? "(no orders)" : o.Item);
        foreach (var line in left) Console.WriteLine(line);
    }
}

