interface IPricingRule { decimal Apply(decimal price); }
class VipRule : IPricingRule { public decimal Apply(decimal p) => p * 0.90m; }
class BlackFridayRule : IPricingRule { public decimal Apply(decimal p) => p * 0.80m; }
// A new rule is a new class: PriceCalculator below never changes (open for extension, closed for modification).
class RoundingRule : IPricingRule { public decimal Apply(decimal p) => Math.Round(p, 0); }

class PriceCalculator
{
    private readonly IEnumerable<IPricingRule> _rules;   // depends on the abstraction, not on concrete rules
    public PriceCalculator(IEnumerable<IPricingRule> rules) { _rules = rules; }
    public decimal Total(decimal basePrice) => _rules.Aggregate(basePrice, (price, rule) => rule.Apply(price));
}

class Program
{
    // Time O(r) for r rules, space O(1).
    static void Main()
    {
        var plain = new PriceCalculator(new IPricingRule[] { });
        var vip = new PriceCalculator(new IPricingRule[] { new VipRule() });
        var bf = new PriceCalculator(new IPricingRule[] { new VipRule(), new BlackFridayRule(), new RoundingRule() });
        Console.WriteLine("base price 99.99");
        Console.WriteLine("no rules           : " + plain.Total(99.99m));
        Console.WriteLine("vip                : " + vip.Total(99.99m));
